`include "prim_assert.sv"

module aes
  import aes_pkg::*;
  import aes_reg_pkg::*;
#(

) (
  input  logic                                      clk_i,
  input  logic                                      rst_ni,
  input  logic                                      rst_shadowed_ni,

  // Idle indicator for clock manager
  output prim_mubi_pkg::mubi4_t                     idle_o,

  // Life cycle
  input  lc_ctrl_pkg::lc_tx_t                       lc_escalate_en_i,

  // Entropy distribution network (EDN) interface
  input  logic                                      clk_edn_i,
  input  logic                                      rst_edn_ni,
  output edn_pkg::edn_req_t                         edn_o,
  input  edn_pkg::edn_rsp_t                         edn_i,

  // Key manager (keymgr) key sideload interface
  input  keymgr_pkg::hw_key_req_t                   keymgr_key_i,

  // Bus interface
  input  tlul_pkg::tl_h2d_t                         tl_i,
  output tlul_pkg::tl_d2h_t                         tl_o,

  // Alerts
  input  prim_alert_pkg::alert_rx_t [NumAlerts-1:0] alert_rx_i,
  output prim_alert_pkg::alert_tx_t [NumAlerts-1:0] alert_tx_o
);

prim_lc_sync #(
  .NumCopies (1)
) u_prim_lc_sync (
  .clk_i,
  .rst_ni,
  .lc_en_i ( lc_escalate_en_i ),
  .lc_en_o ( {lc_escalate_en} )
);

///////////////////
// EDN Interface //
///////////////////

// Internally, we have up to two PRNGs that share the EDN interface for reseeding. Here, we just
// arbitrate the requests. Upsizing of the entropy to the correct width is performed inside the
// PRNGs.
// Reseed operations for the clearing PRNG are initiated by software. Reseed operations for the
// masking PRNG can also be automatically initiated.

assign edn_req_int          = entropy_clearing_req | entropy_masking_req;
// Only forward ACK to PRNG currently requesting entropy. Give higher priority to clearing PRNG.
assign entropy_clearing_ack =  entropy_clearing_req & edn_ack;
assign entropy_masking_ack  = ~entropy_clearing_req & entropy_masking_req & edn_ack;

// Upon escalation or detection of a fatal alert, an EDN request signal can be dropped before
// getting acknowledged. This is okay with respect to AES as the module will need to be reset
// anyway. However, to not leave EDN in a strange state, we hold the request until it's actually
// acknowledged.
assign edn_req        = edn_req_int | edn_req_hold_q;
assign edn_req_hold_d = (edn_req_hold_q | edn_req) & ~edn_ack;

assign unused_edn_fips = edn_i.edn_fips;

//////////
// Core //
//////////

// AES core

assign idle_o = prim_mubi_pkg::mubi4_bool_to_mubi(reg2hw.status.idle.q);

////////////
// Alerts //
////////////

assign alert_test = {
  reg2hw.alert_test.fatal_fault.q &
  reg2hw.alert_test.fatal_fault.qe,
  reg2hw.alert_test.recov_ctrl_update_err.q &
  reg2hw.alert_test.recov_ctrl_update_err.qe
};

`include "prim_assert.sv"

module aes_cipher_control import aes_pkg::*;
#(

sp2v_e                               sub_bytes_out_req;
sp2v_e                               key_expand_out_req;
sp2v_e                               in_valid;
sp2v_e                               out_ready;
sp2v_e                               crypt;
sp2v_e                               dec_key_gen;

state_sel_e     [Sp2VWidth-1:0]      mr_state_sel;
add_rk_sel_e    [Sp2VWidth-1:0]      mr_add_rk_sel;
key_full_sel_e  [Sp2VWidth-1:0]      mr_key_full_sel;
key_dec_sel_e   [Sp2VWidth-1:0]      mr_key_dec_sel;
key_words_sel_e [Sp2VWidth-1:0]      mr_key_words_sel;
round_key_sel_e [Sp2VWidth-1:0]      mr_round_key_sel;

assign sp_in_valid           = {in_valid};
assign sp_out_ready          = {out_ready};
assign sp_crypt              = {crypt};
assign sp_dec_key_gen        = {dec_key_gen};
assign sp_sub_bytes_out_req  = {sub_bytes_out_req};
assign sp_key_expand_out_req = {key_expand_out_req};
assign sp_crypt_q            = {crypt_q};
assign sp_dec_key_gen_q      = {dec_key_gen_q};

assign in_ready_o           = sp2v_e'(sp_in_ready);
assign out_valid_o          = sp2v_e'(sp_out_valid);
assign state_we_o           = sp2v_e'(sp_state_we);
assign sub_bytes_en_o       = sp2v_e'(sp_sub_bytes_en);
assign sub_bytes_out_ack_o  = sp2v_e'(sp_sub_bytes_out_ack);
assign key_full_we_o        = sp2v_e'(sp_key_full_we);
assign key_dec_we_o         = sp2v_e'(sp_key_dec_we);
assign key_expand_en_o      = sp2v_e'(sp_key_expand_en);
assign key_expand_out_ack_o = sp2v_e'(sp_key_expand_out_ack);
assign crypt_d              = sp2v_e'(sp_crypt_d);
assign dec_key_gen_d        = sp2v_e'(sp_dec_key_gen_d);

// Combine single-bit FSM outputs.
// OR: One bit is sufficient to drive the corresponding output bit high.
assign alert_o            = |mr_alert;
assign prng_update_o      = |mr_prng_update;
assign prng_reseed_req_o  = |mr_prng_reseed_req;
assign key_expand_clear_o = |mr_key_expand_clear;
// AND: Only if all bits are high, the corresponding status is signaled which will lead to
// the clearing of these trigger bits.
assign prng_reseed_d      = &mr_prng_reseed_d;
assign key_clear_d        = &mr_key_clear_d;
assign data_out_clear_d   = &mr_data_out_clear_d;

always_comb begin : combine_sparse_signals
  state_sel_o     = state_sel_e'({StateSelWidth{1'b0}});
  add_rk_sel_o    = add_rk_sel_e'({AddRKSelWidth{1'b0}});
  key_full_sel_o  = key_full_sel_e'({KeyFullSelWidth{1'b0}});
  key_dec_sel_o   = key_dec_sel_e'({KeyDecSelWidth{1'b0}});
  key_words_sel_o = key_words_sel_e'({KeyWordsSelWidth{1'b0}});
  round_key_sel_o = round_key_sel_e'({RoundKeySelWidth{1'b0}});
  mr_err          = 1'b0;

  for (int i = 0; i < Sp2VWidth; i++) begin
    state_sel_o     = state_sel_e'({state_sel_o}         | {mr_state_sel[i]});
    add_rk_sel_o    = add_rk_sel_e'({add_rk_sel_o}       | {mr_add_rk_sel[i]});
    key_full_sel_o  = key_full_sel_e'({key_full_sel_o}   | {mr_key_full_sel[i]});
    key_dec_sel_o   = key_dec_sel_e'({key_dec_sel_o}     | {mr_key_dec_sel[i]});
    key_words_sel_o = key_words_sel_e'({key_words_sel_o} | {mr_key_words_sel[i]});
    round_key_sel_o = round_key_sel_e'({round_key_sel_o} | {mr_round_key_sel[i]});
  end

  for (int i = 0; i < Sp2VWidth; i++) begin
    if (state_sel_o     != mr_state_sel[i]     ||
        add_rk_sel_o    != mr_add_rk_sel[i]    ||
        key_full_sel_o  != mr_key_full_sel[i]  ||
        key_dec_sel_o   != mr_key_dec_sel[i]   ||
        key_words_sel_o != mr_key_words_sel[i] ||
        round_key_sel_o != mr_round_key_sel[i]) begin
      mr_err = 1'b1;
    end
  end
end

always_comb begin : combine_counter_signals
  rnd_ctr     = '0;
  rnd_ctr_err = 1'b0;
  for (int i = 0; i < Sp2VWidth; i++) begin
    rnd_ctr |= mr_rnd_ctr[i];
  end

  for (int i = 0; i < Sp2VWidth; i++) begin
    if (rnd_ctr != mr_rnd_ctr[i]) begin
      rnd_ctr_err = 1'b1;
    end
  end
end

always_ff @(posedge clk_i or negedge rst_ni) begin : reg_fsm
  if (!rst_ni) begin
    prng_reseed_q      <= 1'b0;
    key_clear_q        <= 1'b0;
    data_out_clear_q   <= 1'b0;
  end else begin
    prng_reseed_q      <= prng_reseed_d;
    key_clear_q        <= key_clear_d;
    data_out_clear_q   <= data_out_clear_d;
  end
end

assign key_expand_op_o    = (dec_key_gen_d == SP2V_HIGH  ||
                             dec_key_gen_q == SP2V_HIGH) || CiphOpFwdOnly ? CIPH_FWD : op_i;
assign key_expand_round_o = rnd_ctr;

// Let the main controller know whate we are doing.
assign crypt_o          = crypt_q;
assign dec_key_gen_o    = dec_key_gen_q;
assign prng_reseed_o    = prng_reseed_q;
assign key_clear_o      = key_clear_q;
assign data_out_clear_o = data_out_clear_q;

logic [Sp2VWidth-1:0] crypt_q_raw;
prim_flop #(
  .Width      ( Sp2VWidth            ),
  .ResetValue ( Sp2VWidth'(SP2V_LOW) )
) u_crypt_regs (
  .clk_i  ( clk_i       ),
  .rst_ni ( rst_ni      ),
  .d_i    ( crypt_d     ),
  .q_o    ( crypt_q_raw )
);

logic [Sp2VWidth-1:0] dec_key_gen_q_raw;
prim_flop #(
  .Width      ( Sp2VWidth            ),
  .ResetValue ( Sp2VWidth'(SP2V_LOW) )
) u_dec_key_gen_regs (
  .clk_i  ( clk_i             ),
  .rst_ni ( rst_ni            ),
  .d_i    ( dec_key_gen_d     ),
  .q_o    ( dec_key_gen_q_raw )
);

// We use vectors of sparsely encoded signals to reduce code duplication.
localparam int unsigned NumSp2VSig = 8;

assign sp2v_sig[0] = in_valid_i;
assign sp2v_sig[1] = out_ready_i;
assign sp2v_sig[2] = crypt_i;
assign sp2v_sig[3] = dec_key_gen_i;
assign sp2v_sig[4] = sp2v_e'(crypt_q_raw);
assign sp2v_sig[5] = sp2v_e'(dec_key_gen_q_raw);
assign sp2v_sig[6] = sub_bytes_out_req_i;
assign sp2v_sig[7] = key_expand_out_req_i;

// All signals inside sp2v_sig except for sub_bytes/key_expand_out_req_i are driven and consumed
// by multi-rail FSMs.

  assign in_valid           = sp2v_sig_chk[0];
  assign out_ready          = sp2v_sig_chk[1];
  assign crypt              = sp2v_sig_chk[2];
  assign dec_key_gen        = sp2v_sig_chk[3];
  assign crypt_q            = sp2v_sig_chk[4];
  assign dec_key_gen_q      = sp2v_sig_chk[5];
  assign sub_bytes_out_req  = sp2v_sig_chk[6];
  assign key_expand_out_req = sp2v_sig_chk[7];

  // Collect encoding errors.
  // We instantiate the checker modules as close as possible to where the sparsely encoded signals
  // are used. Here, we collect also encoding errors detected in other places of the cipher core.
  assign sp_enc_err = |sp2v_sig_err | sp_enc_err_i;

  ////////////////
  // Assertions //
  ////////////////

  // Selectors must be known/valid
  `ASSERT(AesCiphOpValid, cfg_valid_i |-> op_i inside {
      CIPH_FWD,
      CIPH_INV
      })

endmodule

`include "prim_assert.sv"

module aes_cipher_control_fsm import aes_pkg::*;
#(

assign unused_cfg_valid = cfg_valid_i;

// Tie off unused inputs.
if (!SecMasking) begin : gen_unused_prng_reseed

  assign unused_prng_reseed = prng_reseed_i;
end

// Signals
aes_cipher_ctrl_e aes_cipher_ctrl_ns, aes_cipher_ctrl_cs;

always_comb begin : aes_cipher_ctrl_fsm

  // Handshake signals
  in_ready_o           = 1'b0;
  out_valid_o          = 1'b0;

  // Masking PRNG signals
  prng_update_o        = 1'b0;
  prng_reseed_req_o    = 1'b0;

  // Cipher data path
  state_sel_o          = STATE_ROUND;
  state_we_o           = 1'b0;
  add_rk_sel_o         = ADD_RK_ROUND;
  sub_bytes_en_o       = 1'b0;
  sub_bytes_out_ack_o  = 1'b0;

  // Key expand data path
  key_full_sel_o       = KEY_FULL_ROUND;
  key_full_we_o        = 1'b0;
  key_dec_sel_o        = KEY_DEC_EXPAND;
  key_dec_we_o         = 1'b0;
  key_expand_en_o      = 1'b0;
  key_expand_out_ack_o = 1'b0;
  key_expand_clear_o   = 1'b0;
  key_words_sel_o      = KEY_WORDS_ZERO;
  round_key_sel_o      = ROUND_KEY_DIRECT;

  // FSM
  aes_cipher_ctrl_ns   = aes_cipher_ctrl_cs;
  num_rounds_d         = num_rounds_q;
  rnd_ctr_d            = rnd_ctr_q;
  crypt_d_o            = crypt_q_i;
  dec_key_gen_d_o      = dec_key_gen_q_i;
  prng_reseed_d_o      = prng_reseed_q_i;
  key_clear_d_o        = key_clear_q_i;
  data_out_clear_d_o   = data_out_clear_q_i;
  prng_reseed_done_d   = prng_reseed_done_q | prng_reseed_ack_i;
  advance              = 1'b0;
  cyc_ctr_d            = (SecSBoxImpl == SBoxImplDom) ? cyc_ctr_q + 3'd1 : 3'd0;

  // Alert
  alert_o              = 1'b0;

  unique case (aes_cipher_ctrl_cs)

    CIPHER_CTRL_IDLE: begin
      cyc_ctr_d = 3'd0;

      // Signal that we are ready, wait for handshake.
      in_ready_o = 1'b1;
      if (in_valid_i) begin
        if (SecMasking && prng_reseed_i && !dec_key_gen_i && !crypt_i) begin
          // Reseed the masking PRNG without starting encryption/decryption or generation of the
          // start key for decryption.
          prng_reseed_d_o    = 1'b1;
          prng_reseed_done_d = 1'b0;
          aes_cipher_ctrl_ns = CIPHER_CTRL_PRNG_RESEED;

        end else if (key_clear_i || data_out_clear_i) begin
          // Clear internal key registers. The cipher core muxes are used to clear the data
          // output registers.
          key_clear_d_o      = key_clear_i;
          data_out_clear_d_o = data_out_clear_i;

          // To clear the data output registers, we must first clear the state.
          aes_cipher_ctrl_ns = data_out_clear_i ? CIPHER_CTRL_CLEAR_S : CIPHER_CTRL_CLEAR_KD;

        end else if (dec_key_gen_i || crypt_i) begin
          // Start encryption/decryption or generation of start key for decryption.
          crypt_d_o       = ~dec_key_gen_i & crypt_i;
          dec_key_gen_d_o =  dec_key_gen_i;

          // Latch whether we shall reseed the masking PRNG.
          prng_reseed_d_o = SecMasking & prng_reseed_i;

          // Load input data to state
          state_sel_o = dec_key_gen_i ? STATE_CLEAR : STATE_INIT;
          state_we_o  = 1'b1;

          // Make the masking PRNG advance. The current pseudo-random data is used to mask the
          // input data.
          prng_update_o = SecMasking;

          // Init key expand
          key_expand_clear_o = 1'b1;

          // Load full key
          key_full_sel_o = dec_key_gen_i ? KEY_FULL_ENC_INIT :
                      (op_i == CIPH_FWD) ? KEY_FULL_ENC_INIT :
                      (op_i == CIPH_INV) ? KEY_FULL_DEC_INIT :
                                           KEY_FULL_ENC_INIT;
          key_full_we_o  = 1'b1;

          // Load num_rounds, initialize round counter.
          num_rounds_d = (key_len_i == AES_128) ? 4'd10 :
                         (key_len_i == AES_192) ? 4'd12 :
                                                  4'd14;
          rnd_ctr_d          = '0;
          aes_cipher_ctrl_ns = CIPHER_CTRL_INIT;

        end else begin
          // Handshake without a valid command. We should never get here. If we do (e.g. via a
          // malicious glitch), error out immediately.
          aes_cipher_ctrl_ns = CIPHER_CTRL_ERROR;
        end
      end
    end

    CIPHER_CTRL_INIT: begin
      // Initial round: just add key to state
      add_rk_sel_o = ADD_RK_INIT;

      // Select key words for initial add_round_key
      key_words_sel_o = (dec_key_gen_q_i)            ? KEY_WORDS_ZERO :
          (key_len_i == AES_128)                     ? KEY_WORDS_0123 :
          (key_len_i == AES_192 && op_i == CIPH_FWD) ? KEY_WORDS_0123 :
          (key_len_i == AES_192 && op_i == CIPH_INV) ? KEY_WORDS_2345 :
          (key_len_i == AES_256 && op_i == CIPH_FWD) ? KEY_WORDS_0123 :
          (key_len_i == AES_256 && op_i == CIPH_INV) ? KEY_WORDS_4567 : KEY_WORDS_ZERO;

      // Clear masking PRNG reseed status.
      prng_reseed_done_d = 1'b0;

      // AES-256 has two round keys available right from beginning. Pseudo-random data is
      // required by KeyExpand only.
      if (key_len_i != AES_256) begin
        // Advance in sync with KeyExpand. Based on the S-Box implementation, it can take
        // multiple cycles to finish. Wait for handshake. The DOM S-Boxes consume fresh PRD
        // only in the first clock cycle and that PRD is taken from the buffer stage updated
        // based on key_full_we_o. The PRNG itself is updated in every clock cycle to increase
        // the noise.
        advance         = key_expand_out_req_i & cyc_ctr_expr;
        prng_update_o   = SecMasking;
        key_expand_en_o = 1'b1;
        if (advance) begin
          key_expand_out_ack_o = 1'b1;
          state_we_o           = ~dec_key_gen_q_i;
          key_full_we_o        = 1'b1;
          rnd_ctr_d            = rnd_ctr_q + 4'b0001;
          cyc_ctr_d            = 3'd0;
          aes_cipher_ctrl_ns   = CIPHER_CTRL_ROUND;
        end
      end else begin
        prng_update_o      = SecMasking;
        state_we_o         = ~dec_key_gen_q_i;
        rnd_ctr_d          = rnd_ctr_q + 4'b0001;
        cyc_ctr_d          = 3'd0;
        aes_cipher_ctrl_ns = CIPHER_CTRL_ROUND;
      end
    end

    CIPHER_CTRL_ROUND: begin
      // Normal rounds

      // Select key words for add_round_key
      key_words_sel_o = (dec_key_gen_q_i)            ? KEY_WORDS_ZERO :
          (key_len_i == AES_128)                     ? KEY_WORDS_0123 :
          (key_len_i == AES_192 && op_i == CIPH_FWD) ? KEY_WORDS_2345 :
          (key_len_i == AES_192 && op_i == CIPH_INV) ? KEY_WORDS_0123 :
          (key_len_i == AES_256 && op_i == CIPH_FWD) ? KEY_WORDS_4567 :
          (key_len_i == AES_256 && op_i == CIPH_INV) ? KEY_WORDS_0123 : KEY_WORDS_ZERO;

      // Keep requesting PRNG reseeding until it is acknowledged.
      prng_reseed_req_o = SecMasking & prng_reseed_q_i & ~prng_reseed_done_q;

      // Select round key: direct or mixed (equivalent inverse cipher)
      round_key_sel_o = (op_i == CIPH_FWD) ? ROUND_KEY_DIRECT :
                        (op_i == CIPH_INV) ? ROUND_KEY_MIXED  : ROUND_KEY_DIRECT;

      // Advance in sync with SubBytes and KeyExpand. Based on the S-Box implementation, both can
      // take multiple cycles to finish. Wait for handshake. The DOM S-Boxes consume fresh PRD
      // only in the first clock cycle and that PRD is taken from the buffer stages updated
      // with state_we_o / based on key_full_we_o. The PRNG itself is updated in every clock
      // cycle to increase the noise.
      advance = key_expand_out_req_i & cyc_ctr_expr & (dec_key_gen_q_i | sub_bytes_out_req_i);
      prng_update_o   = SecMasking;
      sub_bytes_en_o  = ~dec_key_gen_q_i;
      key_expand_en_o = 1'b1;

      if (advance) begin
        sub_bytes_out_ack_o  = ~dec_key_gen_q_i;
        key_expand_out_ack_o = 1'b1;

        state_we_o    = ~dec_key_gen_q_i;
        key_full_we_o = 1'b1;

        // Update round
        rnd_ctr_d     = rnd_ctr_q + 4'b0001;
        cyc_ctr_d     = 3'd0;

        // Are we doing the last regular round?
        if (rnd_ctr_q >= num_rounds_regular) begin
          aes_cipher_ctrl_ns = CIPHER_CTRL_FINISH;

          if (dec_key_gen_q_i) begin
            // Write decryption key.
            key_dec_we_o = 1'b1;

            // Indicate that we are done, try to perform the handshake. But we don't wait here.
            // If we don't get the handshake now, we will wait in the finish state. When using
            // masking, we only finish if the masking PRNG has been reseeded.
            out_valid_o = SecMasking ? (prng_reseed_q_i ? prng_reseed_done_q : 1'b1) : 1'b1;
            if (out_valid_o && out_ready_i) begin
              // Go to idle state directly.
              dec_key_gen_d_o    = 1'b0;
              prng_reseed_d_o    = 1'b0;
              aes_cipher_ctrl_ns = CIPHER_CTRL_IDLE;
            end
          end
        end // rnd_ctr_q
      end // SubBytes/KeyExpand REQ/ACK
    end

    CIPHER_CTRL_FINISH: begin
      // Final round

      // Select key words for add_round_key
      key_words_sel_o = (dec_key_gen_q_i)            ? KEY_WORDS_ZERO :
          (key_len_i == AES_128)                     ? KEY_WORDS_0123 :
          (key_len_i == AES_192 && op_i == CIPH_FWD) ? KEY_WORDS_2345 :
          (key_len_i == AES_192 && op_i == CIPH_INV) ? KEY_WORDS_0123 :
          (key_len_i == AES_256 && op_i == CIPH_FWD) ? KEY_WORDS_4567 :
          (key_len_i == AES_256 && op_i == CIPH_INV) ? KEY_WORDS_0123 : KEY_WORDS_ZERO;

      // Skip mix_columns
      add_rk_sel_o = ADD_RK_FINAL;

      // Keep requesting PRNG reseeding until it is acknowledged.
      prng_reseed_req_o = SecMasking & prng_reseed_q_i & ~prng_reseed_done_q;

      // SEC_CM: DATA_REG.KEY.SCA
      // Once we're done, we won't need the state anymore. We actually clear it when progressing
      // to the next state.
      state_sel_o = STATE_CLEAR;

      // SEC_CM: DATA_REG.LOCAL_ESC
      // Advance in sync with SubBytes. Based on the S-Box implementation, it can take multiple
      // cycles to finish. Only indicate that we are done if:
      // - we have valid output (SubBytes finished),
      // - the masking PRNG has been reseeded (if masking is used),
      // - all mux selector signals are valid (don't release data in case of errors), and
      // - all sparsely encoded signals are valid (don't release data in case of errors).
      // Perform both handshakes simultaneously.
      advance        = (sub_bytes_out_req_i & cyc_ctr_expr) | dec_key_gen_q_i;
      sub_bytes_en_o = ~dec_key_gen_q_i;
      out_valid_o    = (mux_sel_err_i || sp_enc_err_i || op_err_i) ? 1'b0         :
          SecMasking ? (prng_reseed_q_i ? prng_reseed_done_q & advance : advance) : advance;

      // Stop updating the cycle counter once we have valid output.
      cyc_ctr_d =
          (SecSBoxImpl == SBoxImplDom) ? (!advance ? cyc_ctr_q + 3'd1 : cyc_ctr_q) : 3'd0;

      // The DOM S-Boxes consume fresh PRD only in the first clock cycle and that PRD is taken
      // from the buffer stages updated with state_we_o / based on key_full_we_o. The PRNG itself
      // is updated in every but the last processing clock cycle to increase the noise. Once the
      // processing is all done (e.g. if we're just waiting for the PRNG reseeding to finish or
      // if we're waiting for out_ready_i), the PRNG is no longer updated to save power. In the
      // very last clock cycle, we update the PRNG again to get ready for the next block.
      prng_update_o =
          ((SecSBoxImpl == SBoxImplDom) ? !advance : 1'b0) | (out_valid_o & out_ready_i);

      if (out_valid_o && out_ready_i) begin
        sub_bytes_out_ack_o = ~dec_key_gen_q_i;

        // Clear the state.
        state_we_o          = 1'b1;
        crypt_d_o           = 1'b0;
        cyc_ctr_d           = 3'd0;
        // If we were generating the decryption key and didn't get the handshake in the last
        // regular round, we should clear dec_key_gen now.
        dec_key_gen_d_o     = 1'b0;
        prng_reseed_d_o     = 1'b0;
        aes_cipher_ctrl_ns  = CIPHER_CTRL_IDLE;
      end
    end

    CIPHER_CTRL_PRNG_RESEED: begin
      // Keep requesting PRNG reseeding until it is acknowledged.
      prng_reseed_req_o = prng_reseed_q_i & ~prng_reseed_done_q;

      // Don't update the cycle counter as we don't need it.
      cyc_ctr_d = 3'd0;

      // Once we're done, wait for handshake.
      out_valid_o = prng_reseed_done_q;
      if (out_valid_o && out_ready_i) begin
        prng_reseed_d_o    = 1'b0;
        aes_cipher_ctrl_ns = CIPHER_CTRL_IDLE;
      end
    end

    CIPHER_CTRL_CLEAR_S: begin
      // Clear the state with pseudo-random data.
      state_we_o         = 1'b1;
      state_sel_o        = STATE_CLEAR;
      aes_cipher_ctrl_ns = CIPHER_CTRL_CLEAR_KD;
    end

    CIPHER_CTRL_CLEAR_KD: begin
      // Clear internal key registers and/or external data output registers.
      if (key_clear_q_i) begin
        key_full_sel_o = KEY_FULL_CLEAR;
        key_full_we_o  = 1'b1;
        key_dec_sel_o  = KEY_DEC_CLEAR;
        key_dec_we_o   = 1'b1;
      end
      if (data_out_clear_q_i) begin
        // Forward the state (previously cleared with psuedo-random data).
        // SEC_CM: DATA_REG.SEC_WIPE
        add_rk_sel_o    = ADD_RK_INIT;
        key_words_sel_o = KEY_WORDS_ZERO;
        round_key_sel_o = ROUND_KEY_DIRECT;
      end
      // Indicate that we are done, wait for handshake.
      out_valid_o = 1'b1;
      if (out_ready_i) begin
        key_clear_d_o      = 1'b0;
        data_out_clear_d_o = 1'b0;
        aes_cipher_ctrl_ns = CIPHER_CTRL_IDLE;
      end
    end

    CIPHER_CTRL_ERROR: begin
      // SEC_CM: CIPHER.FSM.LOCAL_ESC
      // Terminal error state
      alert_o = 1'b1;
    end

    // We should never get here. If we do (e.g. via a malicious glitch), error out immediately.
    default: begin
      aes_cipher_ctrl_ns = CIPHER_CTRL_ERROR;
      alert_o = 1'b1;
    end
  endcase

  // Unconditionally jump into the terminal error state in case a mux selector or a sparsely
  // encoded signal becomes invalid, in case we have detected a fault in the round counter,
  // or if a fatal alert has been triggered.
  if (mux_sel_err_i || sp_enc_err_i || rnd_ctr_err_i || op_err_i || alert_fatal_i) begin
    aes_cipher_ctrl_ns = CIPHER_CTRL_ERROR;
  end
end

always_ff @(posedge clk_i or negedge rst_ni) begin : reg_fsm
  if (!rst_ni) begin
    prng_reseed_done_q <= 1'b0;
    rnd_ctr_q          <= '0;
    num_rounds_q       <= '0;
  end else begin
    prng_reseed_done_q <= prng_reseed_done_d;
    rnd_ctr_q          <= rnd_ctr_d;
    num_rounds_q       <= num_rounds_d;
  end
end

    assign cyc_ctr_q      = cyc_ctr_d;
    assign unused_cyc_ctr = cyc_ctr_q;
    assign cyc_ctr_expr   = 1'b1;
  end

  ////////////////
  // Assertions //
  ////////////////

  // Create a lint error to reduce the risk of accidentally disabling the masking.
  `ASSERT_STATIC_LINT_ERROR(AesCipherControlFsmSecMaskingNonDefault, SecMasking == 1)

  // Create a lint error to reduce the risk of accidentally using a less secure SBox
  // implementation.
  `ASSERT_STATIC_LINT_ERROR(AesCipherControlFsmSecSBoxImplNonDefault, SecSBoxImpl == SBoxImplDom)

  // Selectors must be known/valid
  `ASSERT(AesCiphOpValid, cfg_valid_i |-> op_i inside {
      CIPH_FWD,
      CIPH_INV
      })
  `ASSERT(AesKeyLenValid, cfg_valid_i |-> key_len_i inside {
      AES_128,
      AES_192,
      AES_256
      })
  `ASSERT(AesCipherControlStateValid, !alert_o |-> aes_cipher_ctrl_cs inside {
      CIPHER_CTRL_IDLE,
      CIPHER_CTRL_INIT,
      CIPHER_CTRL_ROUND,
      CIPHER_CTRL_FINISH,
      CIPHER_CTRL_PRNG_RESEED,
      CIPHER_CTRL_CLEAR_S,
      CIPHER_CTRL_CLEAR_KD
      })

endmodule

