module aes_shift_rows (
  input  aes_pkg::ciph_op_e    op_i,
  input  logic [3:0][3:0][7:0] data_i,
  output logic [3:0][3:0][7:0] data_o
);

  import aes_pkg::*;

  // Apply row-wise transformation using AES-defined shifting scheme.
  // Each row has a specific shift offset depending on the operation mode.

always_comb begin
  // Default shift offsets (forward direction)
  row1_shift = 2'h3;
  row3_shift = 2'h1;

  // Override for inverse operation
  if (op_i == CIPH_INV) begin
    row1_shift = 2'h1;
    row3_shift = 2'h3;
  end
end

logic            out_ack_err;

// Every DOM S-Box instance consumes 28 bits of randomness but itself produces 20 bits for use in
// another S-Box instance. For other S-Box implementations, only the bits corresponding to prd_i
// are used. Other bits are ignored and tied to 0.
logic [3:0][3:0][WidthPRDSBox+19:0] in_prd;
logic [3:0][3:0]             [19:0] out_prd;

// SEC_CM: CTRL.SPARSE
// Check sparsely encoded signals.
